Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='publictaskwords', at=datetime(2026, 11, 15, 0, 0, 0), actor='assistant', title='A public task is written deliberately and says nothing about one deployment', body="Only the owner and the main session write to a public store, after door 1 has read the write; the in-app secretary, the triage agent and the box's automated filers write nothing there. A coding session writes no object: it proposes in its pull request's description, and the main session records what it accepts. A public task cites measurements of generated stores only, and a deployment's own figures go on its upkeep chain in a twin task that the public one does not name. A dependency on another store's task is written as a sentence, because a chain's local name means something else on another deployment.", rationale="The leak guard cannot recognise a measurement's numbers or a local chain name by their spelling, so the writer keeps these rules, as for a public issue.", supersedes=()))